{"witnessCode": "import test from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';
test('decode percent-encoded plus after sorting', async () => {
  const input = 'http://example.com?foo=%2B';
  const expected = 'http://example.com/?foo=+';
  const actual = normalizeUrl(input);
  assert.strictEqual(actual, expected);
});"}
